def lis(xs):
    if not xs:
        return 0

    # tails[i] stores the smallest tail of all increasing subsequences of length i+1
    tails = []

    for x in xs:
        # Use binary search to find the insertion point
        # bisect_left finds the first element >= x
        # If x is greater than all elements in tails, append it
        # Otherwise, replace the existing element to maintain the smallest tail property
        import bisect
        idx = bisect.bisect_left(tails, x)

        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x

    return len(tails)
