def valid_sudoku(board):
    # Check rows
    for row in board:
        seen = set()
        for cell in row:
            if cell != '.':
                if cell in seen:
                    return False
                seen.add(cell)

    # Check columns
    for col in range(9):
        seen = set()
        for row in board:
            cell = row[col]
            if cell != '.':
                if cell in seen:
                    return False
                seen.add(cell)

    # Check 3x3 boxes
    for box_row in range(0, 9, 3):
        for box_col in range(0, 9, 3):
            seen = set()
            for i in range(3):
                for j in range(3):
                    cell = board[box_row + i][box_col + j]
                    if cell != '.':
                        if cell in seen:
                            return False
                        seen.add(cell)

    return True
